    assert_eq!(maior(3, 2), true);
}

#[test]
fn testa_dois_e_menor_que_tres() {
    assert_eq!(menor(2, 3), true);
}

#[test]
fn testa_iguais_nao_sao_maior_nem_menor() {
    assert_eq!(maior(4, 4), false);
    assert_eq!(menor(4, 4), false);
